query=query WayfinderMapList($owner: String!, $repo: String!, $labels: [String!]!, $after: String) {
  repository(owner: $owner, name: $repo) {
    labels(query: "wayfinder:", first: 100) {
      nodes { name }
    }
    issues(labels: $labels, states: [OPEN], first: 100, after: $after, orderBy: { field: CREATED_AT, direction: ASC }) {
      pageInfo { hasNextPage endCursor }
      nodes { number }
    }
  }
  rateLimit { remaining resetAt }
}
